class Base {
public:    int p_pub;
protected: int p_prot;
private:   int p_priv;
};

// Private inheritance transforms Base access:
// Public/Protected Base members become Private in D1
class D1_Private : private Base {
public:
    void test_d1() { p_pub = 1; p_prot = 2; } // OK: Accessible inside D1
};

class D2_Final : public D1_Private {
    void test_d2() {
        // p_pub = 3; // ERROR: Inherited members are private to D1_Private
    }
};

// Base members are inaccessible from outside D1 (or D2 instance)
// D1_Private d; d.p_pub; // ERROR
// D2_Final d2; d2.p_pub; // ERROR
